'use strict';
const $=id=>document.getElementById(id), C=AppCore;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state,selected=null,timer,failed=false;
const uid=()=>Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const qrPayload=id=>`de.modulbuch.anlagen://oauth/dropbox?asset=${encodeURIComponent(id)}`;
const qrCache=new Map();
function qrMatrix(id){if(qrCache.has(id))return qrCache.get(id);if(!window.QRRuntime)throw Error('QR-Generator ist nicht verfügbar.');const m=QRRuntime.matrix(qrPayload(id));qrCache.set(id,m);return m;}
function qrVisual(a){try{return QRRuntime.svgData(qrMatrix(a.id),a.name,a.y,a.x);}catch(e){return '';}}
function plainQrVisual(payload){try{const rows=QRRuntime.matrix(payload).split('\n'),n=rows.length,q=4,size=n+q*2,parts=[`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${size} ${size}" shape-rendering="crispEdges"><rect width="100%" height="100%" fill="white"/>`];for(let y=0;y<n;y++)for(let x=0;x<n;x++)if(rows[y][x]==='1')parts.push(`<rect x="${x+q}" y="${y+q}" width="1" height="1" fill="black"/>`);parts.push('</svg>');return 'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(parts.join(''));}catch(e){return '';}}
function migrate17(s){const next=C.clone(s);let changed=false;if(!next.modules.includes('BTF')){next.modules.push('BTF');changed=true;}const existing=new Set(next.assets.filter(a=>a.module==='BTF').map(a=>`${a.name.toUpperCase()}\u0000${a.y.toUpperCase()}\u0000${a.x}`));for(const src of (window.BTF_TOOLS||[])){const k=`${src.name.toUpperCase()}\u0000${src.y.toUpperCase()}\u0000${src.x}`;if(existing.has(k))continue;next.assets.push({...src,notes:[],...C.equipment()});existing.add(k);changed=true;}return {state:next,changed};}
function migrateModule1(s){
 const next=C.clone(s);
 if(Number(next.module1SeedVersion||0)>=1)return {state:next,changed:false,added:0};
 let changed=false,added=0;
 const moduleName='Modul 1';
 if(!next.modules.includes(moduleName)){next.modules.push(moduleName);changed=true;}
 const existingNames=new Set(next.assets.filter(a=>a.module===moduleName).map(a=>String(a.name||'').trim().toUpperCase()));
 const existingIds=new Set(next.assets.map(a=>a.id));
 for(const src of (window.MODUL1_TOOLS||[])){
  const name=String(src.name||'').trim().toUpperCase();
  if(!name||existingNames.has(name))continue;
  let id=src.id;
  if(existingIds.has(id)){let n=1;while(existingIds.has(id+'-'+n))n++;id=id+'-'+n;}
  next.assets.push({...src,id,notes:[],...C.equipment()});
  existingNames.add(name);existingIds.add(id);added++;changed=true;
 }
 next.module1SeedVersion=1;
 changed=true;
 return {state:next,changed,added};
}
function migrateAnnex(s){
 const next=C.clone(s);
 if(Number(next.annexSeedVersion||0)>=1)return {state:next,changed:false,added:0};
 let changed=false,added=0;
 const moduleName='Annex';
 if(!next.modules.includes(moduleName)){next.modules.push(moduleName);changed=true;}
 const existingNames=new Set(next.assets.filter(a=>a.module===moduleName).map(a=>String(a.name||'').trim().toUpperCase()));
 const existingIds=new Set(next.assets.map(a=>a.id));
 for(const src of (window.ANNEX_TOOLS||[])){
  const name=String(src.name||'').trim().toUpperCase();
  if(!name||existingNames.has(name))continue;
  let id=src.id;
  if(existingIds.has(id)){let n=1;while(existingIds.has(id+'-'+n))n++;id=id+'-'+n;}
  next.assets.push({...src,id,notes:[],...C.equipment()});
  existingNames.add(name);existingIds.add(id);added++;changed=true;
 }
 next.annexSeedVersion=1;
 changed=true;
 return {state:next,changed,added};
}

function migratePumpUnits(s){
 const next=C.clone(s);if(Number(next.pumpUnitSeedVersion||0)>=1)return {state:next,changed:false,addedAssets:0,addedUnits:0};
 let changed=false,addedAssets=0,addedUnits=0;const pending='Noch nicht zugeordnet';
 const byName=new Map();for(const a of next.assets){const k=String(a.name||'').trim().toUpperCase();if(k&&!byName.has(k))byName.set(k,a);if(!Array.isArray(a.units))a.units=[];}
 for(const [tool,rows] of Object.entries(window.PUMP_UNIT_DATA||{})){
  let a=byName.get(String(tool).trim().toUpperCase());
  if(!a){if(!next.modules.includes(pending))next.modules.push(pending);a={id:'pump-'+String(tool).toLowerCase().replace(/[^a-z0-9]+/g,'-'),name:String(tool).trim().toUpperCase(),module:pending,y:'?',x:'?',verified:false,pumpModel:'',notes:[],...C.equipment()};next.assets.push(a);byName.set(a.name,a);addedAssets++;changed=true;}
  if(!Array.isArray(a.units))a.units=[];const ids=new Set(a.units.map(u=>u.id));
  for(const src of rows){if(ids.has(src.id))continue;a.units.push(C.clone(src));ids.add(src.id);addedUnits++;changed=true;}
 }
 next.pumpUnitSeedVersion=1;changed=true;return {state:next,changed,addedAssets,addedUnits};
}

function migrateModules234(input){
 const next=C.clone(input);if(Number(next.moduleCleanupVersion||0)>=1)return {state:next,changed:false,merged:0};
 const clean=v=>String(v||'').trim().replace(/\s+/g,' '),key=v=>clean(v).toLocaleLowerCase('de');
 const unassigned=new Set(['nicht zugeordnet','noch nicht zugeordnet']);
 const canonical='Nicht zugeordnet';let changed=false,merged=0;
 const wanted=[];const canonByKey=new Map();
 for(const raw of next.modules||[]){let name=clean(raw);if(unassigned.has(key(name)))name=canonical;const k=key(name);if(!k)continue;if(canonByKey.has(k)){merged++;changed=true;continue;}canonByKey.set(k,name);wanted.push(name);if(name!==raw)changed=true;}
 for(const a of next.assets||[]){let name=clean(a.module);if(unassigned.has(key(name)))name=canonical;const k=key(name);let canon=canonByKey.get(k);if(!canon){canon=name||'Unbekannt';canonByKey.set(key(canon),canon);wanted.push(canon);changed=true;}if(a.module!==canon){a.module=canon;changed=true;}}
 next.modules=wanted;next.moduleCleanupVersion=1;changed=true;
 return {state:next,changed,merged};
}

let navReady=false,navApplying=false;
const NAV_TAG='anlagenbuch-web-234';
function navState(view,assetId=''){return {anlagenbuchNav:NAV_TAG,view,assetId};}
function navApplyHome(){selected=null;$('home').hidden=false;$('detail').hidden=true;render();window.scrollTo(0,0);}
function navPushAsset(id){if(!navReady||navApplying)return;const h=history.state;if(h&&h.anlagenbuchNav===NAV_TAG&&h.view==='asset'&&h.assetId===id)return;try{history.pushState(navState('asset',id),'',location.href);}catch(_){}}
function initNavigation234(){
 if(navReady)return;try{history.replaceState(navState('home'),'',location.href);history.pushState(navState('home'),'',location.href);navReady=true;}catch(_){navReady=false;return;}
 window.addEventListener('popstate',e=>{
  if(!navReady)return;
  const dlg=$('modal');
  if(dlg&&dlg.open){dlg.close();try{history.pushState(navState(selected?'asset':'home',selected||''),'',location.href);}catch(_){}return;}
  const h=e.state;
  if(h&&h.anlagenbuchNav===NAV_TAG&&h.view==='asset'&&h.assetId&&state&&state.assets.some(a=>a.id===h.assetId)){
   navApplying=true;showDetail(h.assetId,false);navApplying=false;return;
  }
  if(selected){navApplying=true;navApplyHome();navApplying=false;return;}
  // Auf der Startseite bleibt Zurück innerhalb der App, statt das Fenster/PWA zu schließen.
  try{history.pushState(navState('home'),'',location.href);}catch(_){}
  if(window.toast)toast('Startseite erreicht.');
 });
}

function toast(s){$('toast').textContent=s;$('toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('toast').classList.remove('show'),4500);}
function persist(next){try{next=C.validate(next);const raw=JSON.stringify(next);if(window.Native){if(!Native.save(raw))throw Error('Speichern fehlgeschlagen. Bitte erneut versuchen.');}else localStorage.setItem('anlagenbuch-v1',raw);state=next;return true;}catch(e){toast(e.message);return false;}}
function change(fn){const s=C.clone(state);fn(s);if(!persist(s))return false;render();return true;}
function options(chosen,all=false){return(all?'<option value="">Alle Module</option>':'')+state.modules.map(m=>`<option value="${esc(m)}" ${m===chosen?'selected':''}>${esc(m)}</option>`).join('');}
function activeFaults(a){return (a.faults||[]).filter(f=>f.status!=='resolved');}
function faultClass(a){const rows=activeFaults(a);return rows.some(f=>f.status==='open')?'faultOpen':rows.some(f=>f.status==='in_progress')?'faultProgress':'';}
function faultBadgeHtml(a){const rows=activeFaults(a);if(!rows.length)return '';const open=rows.filter(f=>f.status==='open').length,progress=rows.length-open;return `<span class="faultBadge ${open?'open':'progress'}">${open?`⚠ ${open} offene Störung${open===1?'':'en'}`:`🛠 ${progress} in Bearbeitung`}</span>`;}

function todayOpenRows247(){
 const d=new Date(),date=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
 return (Array.isArray(state&&state.dailyBusiness)?state.dailyBusiness:[]).filter(r=>r&&r.date<=date&&!r.done&&r.assetId&&r.unitId);
}
function todayAssetIds(){return new Set(todayOpenRows247().map(r=>r.assetId));}
function priorityDesignation247(a,u){return ('V-VA-'+String(a&&a.name||'').trim()+' '+String(u&&u.name||'').trim()).trim();}
function resolveFaultUnit247(a,f){
 if(!a||!f)return null;
 let u=f.unitId?(a.units||[]).find(x=>x.id===f.unitId):null;
 if(!u&&f.unitName){const k=String(f.unitName).trim().toUpperCase();u=(a.units||[]).find(x=>String(x.name||'').trim().toUpperCase()===k)||null;}
 return u||null;
}
function priorityUnitRows247(allowedAssets){
 const allowed=new Set((allowedAssets||[]).map(a=>a.id)),rows=new Map(),assetPos=new Map((state.assets||[]).map((a,i)=>[a.id,i]));
 const take=(a,u,p)=>{const key=a.id+'|'+(u?u.id:'__asset__');let r=rows.get(key);if(!r){r={a,u,p,open:0,progress:0,today:false,assetPos:assetPos.get(a.id)||0,unitPos:u?Math.max(0,(a.units||[]).findIndex(x=>x.id===u.id)):9999};rows.set(key,r);}else if(p<r.p)r.p=p;return r;};
 for(const a of state.assets||[]){if(allowed.size&&!allowed.has(a.id))continue;for(const f of activeFaults(a)){const u=resolveFaultUnit247(a,f),r=take(a,u,f.status==='open'?0:1);if(f.status==='open')r.open++;else if(f.status==='in_progress')r.progress++;}}
 for(const t of todayOpenRows247()){if(allowed.size&&!allowed.has(t.assetId))continue;const a=(state.assets||[]).find(x=>x.id===t.assetId),u=a&&(a.units||[]).find(x=>x.id===t.unitId);if(a&&u)take(a,u,2).today=true;}
 return [...rows.values()].sort((x,y)=>x.p-y.p||x.assetPos-y.assetPos||x.unitPos-y.unitPos);
}
function priorityUnitBadges247(r){const b=[];if(r.open)b.push(`<span class="faultBadge open">⚠ ${r.open} offene Störung${r.open===1?'':'en'}</span>`);if(r.progress)b.push(`<span class="faultBadge progress">🛠 ${r.progress} in Bearbeitung</span>`);if(r.today)b.push('<span class="todayBadge">Tagesgeschäft</span>');return b.join('');}
function priorityUnitCardHtml247(r){
 const title=r.u?priorityDesignation247(r.a,r.u):r.a.name,target=r.u?`data-open-priority-unit="${esc(r.a.id)}|${esc(r.u.id)}"`:`data-open="${esc(r.a.id)}"`,cls=r.open?'faultOpen':r.progress?'faultProgress':'';
 const sub=r.u?`Tool ID ${esc(r.a.name)} · ${esc(r.a.module)} · Y ${esc(r.a.y)} / X ${esc(r.a.x)}`:`Störung ohne Unit-Zuordnung · ${esc(r.a.module)} · Y ${esc(r.a.y)} / X ${esc(r.a.x)}`;
 return `<button class="card ${cls}" ${target}><span><strong class="name">${esc(title)}</strong><small>${sub}</small>${priorityUnitBadges247(r)}</span><span class="arrow">›</span></button>`;
}
function todayBadgeHtml(a,todayIds){if(!todayIds||!todayIds.has(a.id)||activeFaults(a).length)return '';return '<span class="todayBadge">Tagesgeschäft</span>';}

function updateHeaderSummary(){
 try{
  if(!state||!Array.isArray(state.assets))return;
  let open=0,progress=0;
  for(const a of state.assets)for(const f of (a.faults||[])){if(f.status==='open')open++;else if(f.status==='in_progress')progress++;}
  let day=0;try{day=window.getTodayOpenCount?Number(window.getTodayOpenCount()||0):0;}catch(_){}
  const set=(id,v)=>{const e=$(id);if(e)e.textContent=String(v)};
  set('headerOpenCount',open);set('headerProgressCount',progress);set('headerTodayCount',day);
  const t=$('headerSummaryTime');if(t){const d=new Date();t.textContent=`Aktualisiert ${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`;}
 }catch(_){}
}
window.updateHeaderSummary=updateHeaderSummary;

function render(){
 const m=$('moduleFilter').value;$('moduleFilter').innerHTML=options(m,true);
 const found=C.search(state,$('query').value,$('moduleFilter').value,$('only').checked);$('count').textContent=`${found.length} Anlagen`;
 const todayIds=todayAssetIds(),priorityRows=!$('moduleFilter').value?priorityUnitRows247(found):[];
 const totalFaults=state.assets.reduce((n,a)=>n+activeFaults(a).length,0);if($('faultCount'))$('faultCount').textContent=totalFaults?`Offene Störungen (${totalFaults})`:'Offene Störungen';if(window.updateTodayButton)window.updateTodayButton();if(window.updateHeaderSummary)window.updateHeaderSummary();
 const priorityHtml=priorityRows.length?`<div class="row"><h2>Aktive Units</h2><small>Störung · In Bearbeitung · Tagesgeschäft</small></div>${priorityRows.map(priorityUnitCardHtml247).join('')}<div class="row"><h2>Alle Anlagen</h2></div>`:'';
 const normalHtml=found.map(a=>`<button class="card ${faultClass(a)}" data-open="${esc(a.id)}"><span><strong class="name">${esc(a.name)}</strong><small>${esc(a.module)} · ${a.verified?'Bestätigt':'Noch nicht bestätigt'}${a.notes.length?' · '+a.notes.length+' Notiz'+(a.notes.length===1?'':'en'):''}</small>${faultBadgeHtml(a)}${todayBadgeHtml(a,todayIds)}</span><span class="coord">${esc(a.y)} · ${esc(a.x)}</span><span class="arrow">›</span></button>`).join('');
 $('results').innerHTML=found.length?priorityHtml+normalHtml:'<div class="empty">Keine passende Anlage gefunden.<br>Prüfe die Schreibweise oder lege eine neue Anlage an.</div>';
 if(selected)showDetail(selected,false);
}
function showDetail(id,scroll=true){const a=state.assets.find(x=>x.id===id);if(!a){goHome();return;}if(!navApplying)navPushAsset(id);selected=id;$('home').hidden=true;$('detail').hidden=false;
 const qrf=qrVisual(a),faults=activeFaults(a),open=faults.filter(f=>f.status==='open').length,progress=faults.length-open,fc=faultClass(a);
 $('detail').innerHTML=`<button id="back" class="light">‹ Zur Suche</button><div class="detailHero ${fc}"><span class="moduleLabel">${esc(a.module)}</span><h1>${esc(a.name)}</h1>${faults.length?`<div class="faultBanner"><strong>${open?`⚠ ${open} offene Störung${open===1?'':'en'}`:`🛠 ${progress} Störung${progress===1?'':'en'} in Bearbeitung`}</strong><button id="jumpFaults">Anzeigen</button></div>`:''}<div class="bigCoord"><div><small>KOORDINATE Y</small><strong>${esc(a.y)}</strong></div><div><small>KOORDINATE X</small><strong>${esc(a.x)}</strong></div></div><p class="status ${a.verified?'ok':''}">${a.verified?'✓ Angaben von dir bestätigt.':'Angaben noch nicht bestätigt. Bitte mit dem Original oder vor Ort prüfen.'}</p><div class="actions"><button id="reportFault" class="danger">⚠ Störung melden</button><button id="editAsset" class="light">Anlage bearbeiten</button>${!a.verified?'<button id="verify">Angaben bestätigen</button>':''}</div></div><section class="equipmentBox unitsPriority" id="unitsSection"></section><section class="faultPanel ${open?'open':progress?'inProgress':''}" id="faultSection"><div class="row"><h2>Störungen (${faults.length} aktiv)</h2><button id="allFaults" class="light">Alle Störungen</button></div>${faults.length?faults.sort((x,y)=>String(y.updatedAt).localeCompare(String(x.updatedAt))).map(f=>faultCardHtml(a,f)).join(''):'<div class="empty">Für diese Anlage liegt keine offene Störung vor.</div>'}</section><section class="qrBox" id="qrSection"><div class="row"><h2>QR-Code der Anlage</h2><button id="scanQrDetail" class="light">QR-Code scannen</button></div>${qrf?`<div class="qrPrintCard"><img class="assetQr" src="${qrf}" alt="QR-Code ${esc(a.name)}"></div><p class="hint">Der QR-Code wird direkt von der App aus der festen Anlagen-ID erzeugt. Dadurch bekommt auch jede neu angelegte Anlage sofort einen QR-Code.</p><div class="actions qrNoPrint"><button id="printQr">QR-Code drucken</button><button id="saveQr" class="light">QR-Code als Bild speichern</button></div>`:`<div class="empty">QR-Code konnte nicht erzeugt werden.</div>`}</section><div id="equipment"></div><section class="equipmentBox" id="handlingSection"></section><div class="row" id="notesSection"><h2>Notizen / Arbeiten (${a.notes.length})</h2><button id="addNote">+ Eintrag</button></div><p class="hint">Was wurde gewechselt, repariert oder umgebaut?</p><div>${a.notes.length?[...a.notes].sort((n,b)=>b.date.localeCompare(n.date)).map(n=>`<article class="note"><div class="row"><time>${esc(n.date.split('-').reverse().join('.'))}</time><span class="workType ${n.workType==='stoerung'?'workFault':n.workType==='turnus'?'workTurnus':''}">${esc(workTypeLabel(n.workType))}</span></div><p class="hint"><strong>Monteure:</strong> ${esc(n.technicians||'nicht hinterlegt')}</p><p>${esc(n.text)}</p><div class="actions"><button class="light" data-edit-note="${esc(n.id)}">Bearbeiten</button><button class="danger" data-del-note="${esc(n.id)}">Löschen</button></div></article>`).join(''):'<div class="empty">Noch keine Arbeiten eingetragen.</div>'}</div>`;
 renderUnits(a);if($('equipment'))$('equipment').innerHTML='';if($('handlingSection'))$('handlingSection').hidden=true;if($('notesSection')){$('notesSection').hidden=true;let z=$('notesSection').nextElementSibling;if(z)z.hidden=true;z=z&&z.nextElementSibling;if(z)z.hidden=true;}$('back').onclick=goHome;$('editAsset').onclick=()=>assetForm(a.id);$('reportFault').onclick=()=>faultForm(a.id);$('allFaults').onclick=()=>faultOverview();if($('jumpFaults'))$('jumpFaults').onclick=()=>$('faultSection').scrollIntoView({behavior:'smooth',block:'start'});if($('scanQrDetail'))$('scanQrDetail').onclick=scanQr;if($('printQr'))$('printQr').onclick=()=>{document.body.classList.add('printQrMode');if(window.Native&&Native.printQr)Native.printQr();else window.print();setTimeout(()=>document.body.classList.remove('printQrMode'),7000);};if($('saveQr'))$('saveQr').onclick=()=>{try{if(window.Native&&Native.saveGeneratedQr)Native.saveGeneratedQr(a.id,a.name,a.y,a.x,qrMatrix(a.id));else toast('Speichern des QR-Bildes ist in der Android-App verfügbar.');}catch(e){toast('QR-Code konnte nicht erzeugt werden.');}};if($('verify'))$('verify').onclick=()=>{if(change(s=>s.assets.find(x=>x.id===id).verified=true))toast('Angaben bestätigt.');};if(scroll)window.scrollTo(0,0);
}

function sitePlanPanel(){
 const plan=state.sitePlan||C.defaultSitePlan();
 modal(`<h2>Lageplan Gelände</h2><p class="hint">Der Lageplan gilt für alle Mitarbeiter. Er wird mit jeder Sicherung gespeichert und bei einer Dropbox-Wiederherstellung auf das andere Gerät mitgeladen.</p><p><strong>${esc(plan.imageName||'Lageplan Gelände')}</strong></p><div class="actions"><button id="openSitePlan">Lageplan öffnen</button><button id="changeSitePlan" class="light">Bild ändern</button><button id="resetSitePlan" class="light">Mitgelieferten Plan verwenden</button><button id="cancel" class="light">Schließen</button></div><p class="hint">Wenn sich das Gelände durch einen Anbau ändert, kannst du hier jederzeit ein neues JPG-, PNG- oder WebP-Bild auswählen. Beim nächsten Backup wird automatisch der neue Plan gesichert.</p>`);
 $('openSitePlan').onclick=()=>{if(window.Native&&Native.openSitePlanImage)Native.openSitePlanImage(plan.imageUri,plan.imageName||'Lageplan Gelände');else toast('Der Lageplan kann in der Android-App geöffnet werden.');};
 $('changeSitePlan').onclick=()=>{if(window.Native&&Native.chooseSitePlanImage)Native.chooseSitePlanImage();else toast('Bildauswahl ist in der Android-App verfügbar.');};
 $('resetSitePlan').onclick=()=>{if(!confirm('Wieder den mitgelieferten Lageplan verwenden?'))return;const old=plan.imageUri;if(change(s=>s.sitePlan=C.defaultSitePlan())){if(window.Native&&Native.releaseSitePlanImage&&old)Native.releaseSitePlanImage(old);$('modal').close();sitePlanPanel();toast('Mitgelieferter Lageplan eingestellt.');}};
}
window.sitePlanImageSelected=(uri,name)=>{try{const old=(state.sitePlan||{}).imageUri||'';if(change(s=>{s.sitePlan={imageName:name||'Lageplan Gelände',imageUri:uri};})){if(old&&old!==uri&&window.Native&&Native.releaseSitePlanImage)Native.releaseSitePlanImage(old);if($('modal').open){$('modal').close();sitePlanPanel();}toast('Neuer Lageplan gespeichert. Er wird ab der nächsten Sicherung mitgesichert.');}}catch(e){toast('Lageplan konnte nicht gespeichert werden.');}};

function workTypeLabel(t){return t==='stoerung'?'Störung':t==='turnus'?'Turnusmäßige Wartung / Wechsel':'Sonstige Arbeit';}
function workSyncEvent(op,a,n,noteId){return{schema:1,eventId:uid(),at:Date.now(),op,asset:{id:a.id,name:a.name,module:a.module,y:a.y,x:a.x,verified:!!a.verified,pumpModel:a.pumpModel||''},note:n?{id:n.id,date:n.date,workType:n.workType||'sonstiges',technicians:n.technicians||'',text:n.text}:{id:noteId}};}
function setWorkSyncMeta(s,e){if(!s.workSyncMeta||typeof s.workSyncMeta!=='object'||Array.isArray(s.workSyncMeta))s.workSyncMeta={};s.workSyncMeta[e.note.id]={at:e.at,eventId:e.eventId,deleted:e.op==='delete',assetId:e.asset.id};}
function queueWorkSync(e){try{if(window.Native&&Native.queueWorkSync)Native.queueWorkSync(JSON.stringify(e));}catch(_){}}
