window.receiveWorkSync=events=>{try{if(!Array.isArray(events)||!events.length)return;const s=C.clone(state);if(!s.workSyncMeta||typeof s.workSyncMeta!=='object'||Array.isArray(s.workSyncMeta))s.workSyncMeta={};let applied=0,created=0;events=[...events].filter(validSyncEvent).sort((a,b)=>a.at-b.at||String(a.eventId).localeCompare(String(b.eventId)));for(const e of events){const meta=s.workSyncMeta[e.note.id];if(!isNewerSyncEvent(e,meta))continue;if(e.op==='delete'){for(const x of s.assets)x.notes=(x.notes||[]).filter(n=>n.id!==e.note.id);setWorkSyncMeta(s,e);applied++;continue;}const n=e.note;if(typeof n.date!=='string'||!/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(n.date)||!['stoerung','turnus','sonstiges'].includes(n.workType)||typeof n.technicians!=='string'||n.technicians.length>500||typeof n.text!=='string'||!n.text.trim()||n.text.length>10000)continue;let a=s.assets.find(x=>x.id===e.asset.id);if(!a){const mod=(typeof e.asset.module==='string'&&e.asset.module.trim()?e.asset.module.trim():'Unbekannt');if(!s.modules.includes(mod))s.modules.push(mod);a={id:e.asset.id,name:String(e.asset.name||e.asset.id).slice(0,100),module:mod,y:String(e.asset.y||'?').slice(0,20),x:String(e.asset.x||'?').slice(0,20),verified:!!e.asset.verified,pumpModel:String(e.asset.pumpModel||'').slice(0,200),notes:[],...C.equipment()};s.assets.push(a);created++;}for(const x of s.assets)if(x.id!==a.id)x.notes=(x.notes||[]).filter(z=>z.id!==n.id);const val={id:n.id,date:n.date,workType:n.workType,technicians:n.technicians,text:n.text};const i=a.notes.findIndex(x=>x.id===n.id);if(i<0)a.notes.push(val);else a.notes[i]=val;setWorkSyncMeta(s,e);applied++;}if(applied&&persist(s)){render();toast(`${applied} Arbeitseintrag${applied===1?'':'e'} automatisch synchronisiert${created?` · ${created} neue Anlage${created===1?'':'n'} ergänzt`:''}.`);}}catch(_){}};
function seedWorkSync(){try{if(!window.Native||!Native.queueWorkSyncBatch)return;const s=C.clone(state);if(!s.workSyncMeta||typeof s.workSyncMeta!=='object'||Array.isArray(s.workSyncMeta))s.workSyncMeta={};const events=[];for(const a of s.assets)for(const n of (a.notes||[]))if(!s.workSyncMeta[n.id]){const e=workSyncEvent('upsert',a,n);events.push(e);setWorkSyncMeta(s,e);}if(events.length){Native.queueWorkSyncBatch(JSON.stringify(events));persist(s);}else Native.queueWorkSyncBatch('[]');}catch(_){}}
