function validFaultSyncEvent(e){return e&&e.schema===1&&typeof e.eventId==='string'&&e.eventId.length<=100&&Number.isFinite(e.at)&&e.at>=0&&['upsert','delete'].includes(e.op)&&e.asset&&typeof e.asset.id==='string'&&e.asset.id.length>0&&e.asset.id.length<=100&&e.fault&&typeof e.fault.id==='string'&&e.fault.id.length>0&&e.fault.id.length<=100;}
