window.reportUnitFault=(assetId,unitId)=>faultForm(assetId,unitId);window.openUnitAt=(assetId,unitId)=>{showDetail(assetId,false);setTimeout(()=>window.openUnitById&&window.openUnitById(unitId),0);};
const FAULT_ALERT_KEY='fault-alerted-ids-v2';
