function freshOpenFault(f){const t=Date.parse(f&&f.reportedAt||'');return !!(f&&f.id&&f.status==='open'&&Number.isFinite(t)&&Date.now()-t>=-60000&&Date.now()-t<300000);}
window.alertNewFaultsOnce=list=>{try{if(!Array.isArray(list)||!list.length)return false;const seen=faultAlertIds(),set=new Set(seen),notify=[];for(const x of list){const f=x&&x.fault;if(!freshOpenFault(f)||set.has(f.id))continue;set.add(f.id);notify.push(x);}if(!notify.length)return false;saveFaultAlertIds([...set]);if(window.FaultAlerts)FaultAlerts.notifyNewFaults(JSON.stringify(notify));const n=notify[notify.length-1];toast(`⚠ Neue Störung: ${n.asset.name} · ${n.fault.description}`);return true;}catch(_){return false;}};
window.receiveFaultSync=events=>{try{if(!Array.isArray(events)||!events.length)return;const s=C.clone(state);if(!s.faultSyncMeta||typeof s.faultSyncMeta!=='object'||Array.isArray(s.faultSyncMeta))s.faultSyncMeta={};let applied=0,created=0;const notifications=[];events=[...events].filter(validFaultSyncEvent).sort((a,b)=>a.at-b.at||String(a.eventId).localeCompare(String(b.eventId)));for(const e of events){const meta=s.faultSyncMeta[e.fault.id];const same=meta&&e.at===meta.at&&e.eventId===meta.eventId;const missing=!s.assets.some(a=>(a.faults||[]).some(f=>f.id===e.fault.id));if(!isNewerSyncEvent(e,meta)&&!(same&&!meta.deleted&&e.op==='upsert'&&missing))continue;if(e.op==='delete'){for(const x of s.assets)x.faults=(x.faults||[]).filter(f=>f.id!==e.fault.id);setFaultSyncMeta(s,e);applied++;continue;}if(!validFault(e.fault))continue;let a=s.assets.find(x=>x.id===e.asset.id);if(!a){const mod=(typeof e.asset.module==='string'&&e.asset.module.trim()?e.asset.module.trim():'Unbekannt');if(!s.modules.includes(mod))s.modules.push(mod);a={id:e.asset.id,name:String(e.asset.name||e.asset.id).slice(0,100),module:mod,y:String(e.asset.y||'?').slice(0,20),x:String(e.asset.x||'?').slice(0,20),verified:!!e.asset.verified,pumpModel:String(e.asset.pumpModel||'').slice(0,200),notes:[],...C.equipment()};s.assets.push(a);created++;}for(const x of s.assets)if(x.id!==a.id)x.faults=(x.faults||[]).filter(z=>z.id!==e.fault.id);const old=(a.faults||[]).find(x=>x.id===e.fault.id),val=C.clone(e.fault),i=(a.faults||[]).findIndex(x=>x.id===val.id);if(i<0)a.faults.push(val);else a.faults[i]=val;setFaultSyncMeta(s,e);applied++;if(!old&&freshOpenFault(val))notifications.push({asset:a,fault:val});}if(applied&&persist(s)){render();refreshFaultOverview();const alarmed=window.alertNewFaultsOnce&&window.alertNewFaultsOnce(notifications);if(!alarmed)toast(`${applied} Störungsmeldung${applied===1?'':'en'} automatisch synchronisiert${created?` · ${created} neue Anlage${created===1?'':'n'} ergänzt`:''}.`);}}catch(_){} };
function seedFaultSync(){try{if(!window.Native||!Native.queueFaultSyncBatch)return;const s=C.clone(state);if(!s.faultSyncMeta||typeof s.faultSyncMeta!=='object'||Array.isArray(s.faultSyncMeta))s.faultSyncMeta={};const events=[];for(const a of s.assets)for(const f of (a.faults||[]))if(!s.faultSyncMeta[f.id]){const e=faultSyncEvent('upsert',a,f);events.push(e);setFaultSyncMeta(s,e);}if(events.length){Native.queueFaultSyncBatch(JSON.stringify(events));persist(s);}else Native.queueFaultSyncBatch('[]');}catch(_){} }
let lastFaultSyncRequestAt=0;
function requestFaultSync(force=false){
 try{
  if(document.hidden||navigator.onLine===false||!window.Native||!Native.syncFaults)return;
  const now=Date.now(),gap=force===true?80:350;
  if(lastFaultSyncRequestAt&&now-lastFaultSyncRequestAt<gap)return;
  Native.syncFaults();lastFaultSyncRequestAt=now;
 }catch(_){}
}
