function faultCardHtml(a,f){return `<article class="faultRecord ${esc(f.status)}"><div class="row"><strong>${f.unitName?esc((f.unitBarcode||f.unitName))+' · ':''}${esc(f.description)}</strong><span class="faultStatus ${esc(f.status)}">${esc(faultStatusLabel(f.status))}</span></div><p class="hint">Gemeldet am ${esc(germanDate(f.reportedDate))} von <strong>${esc(f.reportedBy)}</strong>${f.assignedTo?` · Bearbeitung: <strong>${esc(f.assignedTo)}</strong>`:''}</p>${f.status!=='resolved'?`<div class="actions">${f.status==='open'?`<button data-fault-take="${esc(f.id)}" data-fault-asset="${esc(a.id)}">In Bearbeitung übernehmen</button>`:`<button data-fault-take="${esc(f.id)}" data-fault-asset="${esc(a.id)}" class="light">Bearbeiter ändern</button>`}<button data-fault-resolve="${esc(f.id)}" data-fault-asset="${esc(a.id)}">Störung beheben / erledigen</button></div>`:''}</article>`;}
function faultForm(assetId,unitId=''){const a=state.assets.find(x=>x.id===assetId);if(!a)return;const u=unitId?(a.units||[]).find(x=>x.id===unitId):null;modal(`<h2>Störung melden</h2><p><strong>${u?esc(('V-VA-'+a.name+' '+u.name).trim()):esc(a.name)}</strong> · ${esc(a.module)} · Y ${esc(a.y)} / X ${esc(a.x)}</p><form id="faultForm"><label for="faultBy">Gemeldet von</label><input id="faultBy" name="reportedBy" required maxlength="500" placeholder="Name"><label for="faultText">Störung / Fehlerbeschreibung</label><textarea id="faultText" name="description" required maxlength="10000" placeholder="Was wurde festgestellt?"></textarea><div class="actions"><button type="submit" class="danger">Störung für alle melden</button><button id="cancel" type="button" class="light">Abbrechen</button></div></form><p class="hint">Die Anlage wird bei allen Mitarbeitern farblich als gestört markiert und erscheint unter „Offene Störungen“.</p>`);$('faultForm').onsubmit=e=>{e.preventDefault();const f=e.target.elements,now=new Date().toISOString(),val={id:uid(),reportedDate:today(),reportedAt:now,updatedAt:now,reportedBy:f.reportedBy.value.trim(),description:f.description.value.trim(),status:'open',assignedTo:'',resolvedAt:'',resolutionNoteId:'',unitId:u?u.id:'',unitName:u?u.name:'',unitBarcode:u?('V-VA-'+a.name+' '+u.name).trim():'',unitPumpModel:u?u.pumpModel:''};if(!val.reportedBy||!val.description)return toast('Bitte Melder und Fehlerbeschreibung eintragen.');const event=faultSyncEvent('upsert',a,val);if(change(s=>{const x=s.assets.find(x=>x.id===assetId);x.faults.push(val);setFaultSyncMeta(s,event);})){queueFaultSync(event);$('modal').close();showDetail(assetId,false);toast('Störung gemeldet. Sie wird für alle Mitarbeiter synchronisiert.');}};}
function takeFault(assetId,faultId){const a=state.assets.find(x=>x.id===assetId),f=a&&(a.faults||[]).find(x=>x.id===faultId);if(!f)return;modal(`<h2>Störung in Bearbeitung</h2><p><strong>${esc(a.name)}</strong></p><p>${esc(f.description)}</p><label for="faultAssignee">Bearbeitung durch</label><input id="faultAssignee" value="${esc(f.assignedTo||'')}" maxlength="500" placeholder="Name"><div class="actions"><button id="takeFaultSave">Als „In Bearbeitung“ speichern</button><button id="cancel" class="light">Abbrechen</button></div>`);$('takeFaultSave').onclick=()=>{const who=$('faultAssignee').value.trim();if(!who)return toast('Bitte Name eintragen.');const val={...C.clone(f),status:'in_progress',assignedTo:who,updatedAt:new Date().toISOString(),resolvedAt:'',resolutionNoteId:''},event=faultSyncEvent('upsert',a,val);if(change(s=>{const x=s.assets.find(z=>z.id===assetId),i=x.faults.findIndex(z=>z.id===faultId);x.faults[i]=val;setFaultSyncMeta(s,event);})){queueFaultSync(event);$('modal').close();showDetail(assetId,false);toast('Störung steht jetzt auf „In Bearbeitung“ und wird synchronisiert.');}};}
function resolveFaultForm(assetId,faultId){const a=state.assets.find(x=>x.id===assetId),f=a&&(a.faults||[]).find(x=>x.id===faultId);if(!f)return;modal(`<h2>Störung beheben und erledigen</h2><p><strong>${esc(a.name)}</strong></p><p class="status">${esc(f.description)}</p><form id="resolveFaultForm"><label for="resolveDate">Datum</label><input type="date" id="resolveDate" name="date" value="${today()}" required><label for="resolveTech">Monteure</label><input id="resolveTech" name="technicians" value="${esc(f.assignedTo||'')}" maxlength="500" required placeholder="Name"><label for="resolveText">Durchgeführte Arbeit / Behebung</label><textarea id="resolveText" name="text" maxlength="10000" required placeholder="Was wurde geprüft, repariert oder gewechselt?"></textarea><div class="actions"><button type="submit">Protokoll speichern + Störung erledigt</button><button id="cancel" type="button" class="light">Abbrechen</button></div></form><p class="hint">Der Arbeitseintrag erscheint ganz normal im Tages-/Monatsprotokoll. Erst mit diesem Button verschwindet die Störung aus „Offene Störungen“.</p>`);$('resolveFaultForm').onsubmit=e=>{e.preventDefault();const x=e.target.elements,note={id:uid(),date:x.date.value,workType:'stoerung',technicians:x.technicians.value.trim(),text:x.text.value.trim()};if(!note.technicians||!note.text)return toast('Bitte Monteure und durchgeführte Arbeit eintragen.');const now=new Date().toISOString(),fault={...C.clone(f),status:'resolved',assignedTo:note.technicians,updatedAt:now,resolvedAt:now,resolutionNoteId:note.id},we=workSyncEvent('upsert',a,note),fe=faultSyncEvent('upsert',a,fault);if(change(s=>{const aa=s.assets.find(z=>z.id===assetId),fi=aa.faults.findIndex(z=>z.id===faultId);aa.faults[fi]=fault;aa.notes.push(note);setWorkSyncMeta(s,we);setFaultSyncMeta(s,fe);})){queueWorkSync(we);queueFaultSync(fe);$('modal').close();showDetail(assetId,false);toast('Störung erledigt und Arbeitsprotokoll gespeichert.');}};}
function faultOverview(refreshOnly=false){if(!refreshOnly)requestFaultSync(true);const rows=[];for(const a of state.assets)for(const f of activeFaults(a))rows.push({a,f});rows.sort((x,y)=>(x.f.status==='open'?0:1)-(y.f.status==='open'?0:1)||String(y.f.updatedAt).localeCompare(String(x.f.updatedAt)));modal(`<div class="row"><h2 id="faultOverviewTitle">Offene Störungen</h2><span class="faultStatus ${rows.some(r=>r.f.status==='open')?'open':'in_progress'}">${rows.length} aktiv</span></div><p class="hint">Rot = noch offen. Orange = ein Kollege hat die Bearbeitung übernommen. Erst nach dem Abschlussprotokoll gilt die Störung als erledigt.</p>${rows.length?rows.map(({a,f})=>`<article class="faultRecord ${esc(f.status)}"><div class="row"><strong>${esc(a.name)}${f.unitName?' · '+esc(f.unitBarcode||f.unitName):''}</strong><span class="faultStatus ${esc(f.status)}">${esc(faultStatusLabel(f.status))}</span></div><p class="hint">${esc(a.module)} · Y ${esc(a.y)} / X ${esc(a.x)} · gemeldet von ${esc(f.reportedBy)}</p><p>${esc(f.description)}</p>${f.assignedTo?`<p><strong>Bearbeitung:</strong> ${esc(f.assignedTo)}</p>`:''}<div class="actions"><button data-fault-open="${esc(a.id)}" class="light">Anlage öffnen</button>${f.status==='open'?`<button data-fault-take="${esc(f.id)}" data-fault-asset="${esc(a.id)}">Übernehmen</button>`:''}<button data-fault-resolve="${esc(f.id)}" data-fault-asset="${esc(a.id)}">Beheben / erledigen</button></div></article>`).join(''):'<div class="empty">Aktuell gibt es keine offenen Störungen.</div>'}<div class="actions"><button id="reloadFaultHistory" class="light">Störungen neu abgleichen</button><button id="cancel" class="light">Schließen</button></div>`);$('reloadFaultHistory').onclick=()=>{try{if(window.Native&&Native.resetFaultSyncForRestore){Native.resetFaultSyncForRestore();toast('Störungsabgleich gestartet. Internetverbindung erforderlich.');}else toast('Der Team-Abgleich ist in der Android-App verfügbar.');}catch(e){toast('Abgleich konnte nicht gestartet werden. Bitte Cloud-Einrichtung prüfen.');}};}

function germanDate(d){return String(d||'').split('-').reverse().join('.');}
function protocolOrderTime(n){const m=state.workSyncMeta&&state.workSyncMeta[n.id];if(m&&Number.isFinite(m.at))return m.at;const p=parseInt(String(n.id||'').split('-')[0],36);if(Number.isFinite(p)&&p>946684800000&&p<4102444800000)return p;return Date.parse((n.date||'1970-01-01')+'T00:00:00')||0;}
function protocolEntries(date){const rows=[];for(const a of state.assets)for(const n of (a.notes||[]))if(n.date===date)rows.push({asset:a,note:n});return rows.sort((r,b)=>protocolOrderTime(b.note)-protocolOrderTime(r.note)||b.note.id.localeCompare(r.note.id)||r.asset.name.localeCompare(b.asset.name,'de',{numeric:true}));}
function monthProtocolEntries(month){const rows=[];if(!/^[0-9]{4}-[0-9]{2}$/.test(month))return rows;for(const a of state.assets)for(const n of (a.notes||[]))if(String(n.date||'').startsWith(month+'-'))rows.push({asset:a,note:n});return rows.sort((r,b)=>r.note.date.localeCompare(b.note.date)||protocolOrderTime(r.note)-protocolOrderTime(b.note)||r.asset.name.localeCompare(b.asset.name,'de',{numeric:true}));}
function protocolText(date,rows){const assets=new Set(rows.map(r=>r.asset.id));const lines=[`Tagesprotokoll ${germanDate(date)}`,`${assets.size} Anlage${assets.size===1?'':'n'} · ${rows.length} ${rows.length===1?'Arbeitseintrag':'Arbeitseinträge'}`,''];rows.forEach((r,i)=>{const n=r.note,a=r.asset;lines.push(`${i+1}. ${a.name} · ${a.module} · Y ${a.y} / X ${a.x}`,`Art: ${workTypeLabel(n.workType)}`,`Monteure: ${n.technicians||'nicht hinterlegt'}`,`Arbeit: ${n.text}`,'');});return lines.join('\n');}
function csvCell(v){const s=String(v==null?'':v);return /[;"\r\n]/.test(s)?'"'+s.replace(/"/g,'""')+'"':s;}
function monthProtocolCsv(month,rows){const lines=['Datum;Anlage;Modul;Koordinate Y;Koordinate X;Art;Monteure;Arbeit'];for(const {asset:a,note:n} of rows)lines.push([germanDate(n.date),a.name,a.module,a.y,a.x,workTypeLabel(n.workType),n.technicians||'nicht hinterlegt',n.text].map(csvCell).join(';'));return '\uFEFF'+lines.join('\r\n')+'\r\n';}
function saveMonthProtocol(month){const rows=monthProtocolEntries(month);if(!rows.length)return toast('Für diesen Monat gibt es keine Arbeitseinträge.');const raw=monthProtocolCsv(month,rows);if(window.Native&&Native.saveMonthlyProtocol){Native.saveMonthlyProtocol(month,raw);return;}const url=URL.createObjectURL(new Blob([raw],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`Anlagenbuch-Monatsprotokoll-${month}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function copyDailyProtocol(text){if(window.Native&&Native.copyText){Native.copyText(text);return;}if(navigator.clipboard&&navigator.clipboard.writeText)navigator.clipboard.writeText(text).then(()=>toast('Tagesprotokoll kopiert.')).catch(()=>toast('Kopieren ist auf diesem Gerät nicht verfügbar.'));else toast('Kopieren ist auf diesem Gerät nicht verfügbar.');}
function dailyProtocolPanel(date=today()){
 const rows=protocolEntries(date),assets=new Set(rows.map(r=>r.asset.id)),month=date.slice(0,7),monthRows=monthProtocolEntries(month);
 modal(`<div class="row"><h2>Tagesprotokoll</h2><button id="todayProtocol" class="light">Heute</button></div><label for="protocolDate">Datum</label><input type="date" id="protocolDate" value="${esc(date)}"><p class="hint">${rows.length?`${assets.size} Anlage${assets.size===1?'':'n'} besucht · ${rows.length} ${rows.length===1?'Arbeitseintrag':'Arbeitseinträge'}`:'Für diesen Tag gibt es noch keine Arbeitseinträge.'}</p>${rows.length?rows.map(({asset:a,note:n})=>`<article class="record protocolRecord"><div class="row"><strong>${esc(a.name)}</strong><span class="workType ${n.workType==='stoerung'?'workFault':n.workType==='turnus'?'workTurnus':''}">${esc(workTypeLabel(n.workType))}</span></div><p class="hint">${esc(a.module)} · Y ${esc(a.y)} · X ${esc(a.x)} · ${esc(germanDate(n.date))}</p><p><strong>Monteure:</strong> ${esc(n.technicians||'nicht hinterlegt')}</p><p class="equipmentHint">${esc(n.text)}</p><button class="light" data-protocol-open="${esc(a.id)}">Anlage öffnen</button></article>`).join(''):'<div class="empty">An diesem Tag wurde noch keine Arbeit dokumentiert.</div>'}<div class="actions"><button id="copyProtocol" ${rows.length?'':'disabled'}>Tagesprotokoll kopieren</button></div><hr><h3>Monatsprotokoll für die Abrechnung</h3><label for="protocolMonth">Monat</label><input type="month" id="protocolMonth" value="${esc(month)}"><p id="monthProtocolInfo" class="hint">${monthRows.length?`${monthRows.length} Arbeitseintrag${monthRows.length===1?'':'e'} in diesem Monat.`:'Für diesen Monat gibt es noch keine Arbeitseinträge.'}</p><div class="actions"><button id="saveMonthProtocol" ${monthRows.length?'':'disabled'}>Monatsprotokoll als CSV speichern</button><button id="cancel" class="light">Schließen</button></div><p class="hint">Die Monatsdatei enthält vollständig: Datum, Anlage, Modul, Koordinaten, Arbeitsart, Monteure und Arbeitstext. Die CSV-Datei lässt sich am Computer direkt mit Excel öffnen und für die monatliche Abrechnung weiterverwenden.</p><p class="hint">Bei einer Sicherungswiederherstellung bleiben die aktuellen gemeinsamen Arbeitsprotokolle erhalten. Danach wird der vollständige Protokollverlauf erneut mit Dropbox abgeglichen.</p>`);
 $('protocolDate').onchange=e=>{const d=e.target.value;if(d){$('modal').close();dailyProtocolPanel(d);}};
 $('todayProtocol').onclick=()=>{$('modal').close();dailyProtocolPanel(today());};
 if(rows.length)$('copyProtocol').onclick=()=>copyDailyProtocol(protocolText(date,rows));
 $('protocolMonth').onchange=e=>{const m=e.target.value,r=monthProtocolEntries(m);$('monthProtocolInfo').textContent=r.length?`${r.length} Arbeitseintrag${r.length===1?'':'e'} in diesem Monat.`:'Für diesen Monat gibt es noch keine Arbeitseinträge.';$('saveMonthProtocol').disabled=!r.length;};
 $('saveMonthProtocol').onclick=()=>saveMonthProtocol($('protocolMonth').value);
 document.querySelectorAll('[data-protocol-open]').forEach(b=>b.onclick=()=>{$('modal').close();showDetail(b.dataset.protocolOpen);});
}


function handlingTextHtml(text){return text?`<div class="handlingText">${esc(text)}</div>`:'<p class="empty">Noch kein Text hinterlegt.</p>';}
function instructionById(id){return (state.instructionLibrary||[]).find(x=>x.id===id)||null;}
function renderHandlingInstruction(a){
 const h=a.handlingInstruction||C.emptyHandling(),shared=instructionById(h.libraryId);
 $('handlingSection').innerHTML=`<div class="row"><h2>Hantierungsanweisung</h2><button id="assignHandlingLibrary" class="light">${shared?'Andere Anleitung wählen':'Anleitung zuweisen'}</button></div><p class="hint">Gemeinsame Anleitungen werden nur einmal gespeichert und können beliebig vielen Anlagen desselben Typs zugeordnet werden.</p><div class="handlingPdf"><strong>Gemeinsame Anleitung</strong>${shared?`<p><strong>${esc(shared.title)}</strong>${shared.pumpModel?`<br><small>Typ: ${esc(shared.pumpModel)}</small>`:''}</p>${handlingTextHtml(shared.text)}<p class="hint">${shared.pdfName?esc(shared.pdfName):'Keine PDF in dieser gemeinsamen Anleitung.'}</p><div class="actions">${shared.pdfUri?'<button id="openSharedHandlingPdf">PDF öffnen</button>':''}<button id="clearHandlingLibrary" class="danger">Zuordnung entfernen</button></div>`:'<p class="empty">Noch keine gemeinsame Anleitung zugeordnet.</p>'}</div><hr><div class="row"><strong>Anlagenspezifische Ergänzung</strong><button id="editHandlingText" class="light">Text bearbeiten</button></div><p class="hint">Nur für Besonderheiten dieser einzelnen Anlage.</p>${handlingTextHtml(h.text)}<div class="handlingPdf"><strong>Eigene PDF nur für diese Anlage</strong><p class="hint">${h.pdfName?esc(h.pdfName):'Keine eigene PDF hinterlegt.'}</p><div class="actions"><button id="chooseHandlingPdf" class="light">${h.pdfName?'PDF ersetzen':'PDF hinterlegen'}</button>${h.pdfUri?'<button id="openHandlingPdf">PDF öffnen</button><button id="removeHandlingPdf" class="danger">PDF entfernen</button>':''}</div></div>`;
 $('assignHandlingLibrary').onclick=()=>assignInstructionLibrary(a.id);
 if($('clearHandlingLibrary'))$('clearHandlingLibrary').onclick=()=>{if(change(s=>s.assets.find(x=>x.id===a.id).handlingInstruction.libraryId=''))toast('Gemeinsame Anleitung entfernt.');};
 if($('openSharedHandlingPdf'))$('openSharedHandlingPdf').onclick=()=>Native.openInstructionPdf(shared.pdfUri);
 $('editHandlingText').onclick=handlingTextForm;
 $('chooseHandlingPdf').onclick=()=>{if(window.Native&&Native.chooseInstructionPdf)Native.chooseInstructionPdf('asset:'+a.id);else toast('PDF-Auswahl ist in der Android-App verfügbar.');};
 if($('openHandlingPdf'))$('openHandlingPdf').onclick=()=>{if(window.Native&&Native.openInstructionPdf)Native.openInstructionPdf(h.pdfUri);else toast('PDF-Öffnen ist in der Android-App verfügbar.');};
 if($('removeHandlingPdf'))$('removeHandlingPdf').onclick=()=>{if(!confirm('PDF-Verknüpfung aus dieser Anlage entfernen? Die Originaldatei wird nicht gelöscht.'))return;const uri=h.pdfUri;if(change(s=>{const t=s.assets.find(x=>x.id===selected);t.handlingInstruction.pdfName='';t.handlingInstruction.pdfUri='';})){if(window.Native&&Native.releaseInstructionPdf&&uri)Native.releaseInstructionPdf(uri);toast('PDF-Verknüpfung entfernt.');}};
}
function handlingTextForm(){const a=state.assets.find(x=>x.id===selected),h=a.handlingInstruction||C.emptyHandling();modal(`<h2>Anlagenspezifische Ergänzung</h2><p>${esc(a.name)} · ${esc(a.module)}</p><form id="handlingTextForm"><label for="handlingText">Text nur für diese Anlage</label><textarea id="handlingText" name="text" maxlength="50000" placeholder="Besonderheiten dieser einzelnen Anlage …">${esc(h.text)}</textarea><p class="hint">Die allgemeine Arbeitsreihenfolge sollte in der gemeinsamen Anleitungsbibliothek liegen.</p><div class="actions"><button type="submit">Speichern</button><button type="button" id="cancel" class="light">Abbrechen</button></div></form>`);$('handlingTextForm').onsubmit=e=>{e.preventDefault();const text=e.target.elements.text.value.trim();if(change(s=>s.assets.find(x=>x.id===selected).handlingInstruction.text=text)){$('modal').close();toast('Ergänzung gespeichert.');}};}
function assignInstructionLibrary(assetId){const a=state.assets.find(x=>x.id===assetId),rows=state.instructionLibrary||[];modal(`<h2>Gemeinsame Anleitung zuweisen</h2><p>${esc(a.name)}${a.pumpModel?` · Typ ${esc(a.pumpModel)}`:''}</p>${rows.length?rows.map(i=>`<article class="record"><strong>${esc(i.title)}</strong>${i.pumpModel?`<p class="hint">Typ: ${esc(i.pumpModel)}${a.pumpModel&&i.pumpModel.toLowerCase()===a.pumpModel.toLowerCase()?' · passend zum Pumpenmodell':''}</p>`:''}<p class="hint">${i.pdfName?'PDF: '+esc(i.pdfName):'ohne PDF'}</p><button data-assign-instruction="${esc(i.id)}">Diese Anleitung verwenden</button></article>`).join(''):'<p class="empty">Noch keine gemeinsamen Anleitungen vorhanden.</p>'}<div class="actions"><button id="openLibraryFromAssign" class="light">Anleitungen verwalten</button><button id="cancel" class="light">Abbrechen</button></div>`);document.querySelectorAll('[data-assign-instruction]').forEach(b=>b.onclick=()=>{if(change(s=>s.assets.find(x=>x.id===assetId).handlingInstruction.libraryId=b.dataset.assignInstruction)){$('modal').close();showDetail(assetId,false);toast('Gemeinsame Anleitung zugeordnet.');}});$('openLibraryFromAssign').onclick=()=>{$('modal').close();instructionLibraryPanel();};}
function instructionLibraryPanel(){const rows=state.instructionLibrary||[];modal(`<div class="row"><h2>Hantierungsanweisungen</h2><button id="addInstruction">+ Anleitung</button></div><p class="hint">Eine PDF wird hier nur einmal hinterlegt. Mehrere Anlagen können dieselbe Anleitung verwenden.</p>${rows.length?rows.map(i=>{const used=state.assets.filter(a=>a.handlingInstruction&&a.handlingInstruction.libraryId===i.id).length;return `<article class="record"><strong>${esc(i.title)}</strong>${i.pumpModel?`<p class="hint">Pumpentyp: ${esc(i.pumpModel)}</p>`:''}<p class="hint">${i.pdfName?'PDF: '+esc(i.pdfName):'Keine PDF'} · ${used} Anlage${used===1?'':'n'} zugeordnet</p><div class="actions">${i.pdfUri?`<button class="light" data-open-library-pdf="${esc(i.id)}">PDF öffnen</button>`:''}<button class="light" data-edit-instruction="${esc(i.id)}">Bearbeiten</button><button class="danger" data-delete-instruction="${esc(i.id)}">Löschen</button></div></article>`;}).join(''):'<p class="empty">Noch keine gemeinsamen Anleitungen angelegt.</p>'}<button id="cancel" class="light">Schließen</button>`);$('addInstruction').onclick=()=>instructionLibraryForm();document.querySelectorAll('[data-edit-instruction]').forEach(b=>b.onclick=()=>instructionLibraryForm(b.dataset.editInstruction));document.querySelectorAll('[data-open-library-pdf]').forEach(b=>b.onclick=()=>{const i=instructionById(b.dataset.openLibraryPdf);if(i&&i.pdfUri)Native.openInstructionPdf(i.pdfUri);});document.querySelectorAll('[data-delete-instruction]').forEach(b=>b.onclick=()=>{const id=b.dataset.deleteInstruction,i=instructionById(id),used=state.assets.filter(a=>a.handlingInstruction&&a.handlingInstruction.libraryId===id).length;if(!confirm(`„${i.title}“ löschen? Die Zuordnung wird bei ${used} Anlage${used===1?'':'n'} entfernt. Die Original-PDF wird nicht gelöscht.`))return;const uri=i.pdfUri;if(change(s=>{s.instructionLibrary=s.instructionLibrary.filter(x=>x.id!==id);s.assets.forEach(a=>{if(a.handlingInstruction&&a.handlingInstruction.libraryId===id)a.handlingInstruction.libraryId='';});})){if(uri&&Native.releaseInstructionPdf)Native.releaseInstructionPdf(uri);$('modal').close();instructionLibraryPanel();}});}
function instructionLibraryForm(id){const i=instructionById(id)||{id:id||uid(),title:'',pumpModel:'',text:'',pdfName:'',pdfUri:''};modal(`<h2>${id?'Anleitung bearbeiten':'Gemeinsame Anleitung anlegen'}</h2><form id="instructionLibraryForm"><label for="instructionTitle">Bezeichnung der Anleitung</label><input id="instructionTitle" name="title" value="${esc(i.title)}" maxlength="200" required placeholder="z. B. Cobra NC 0400"><label for="instructionModel">Pumpentyp / Modell</label><input id="instructionModel" name="pumpModel" value="${esc(i.pumpModel)}" maxlength="200" placeholder="z. B. COBRA NC 0400 B"><label for="instructionText">Arbeitsreihenfolge / Text</label><textarea id="instructionText" name="text" maxlength="50000">${esc(i.text)}</textarea><p class="hint">PDF: ${i.pdfName?esc(i.pdfName):'noch keine hinterlegt'}</p><div class="actions"><button type="submit">Speichern</button>${id?`<button type="button" id="chooseLibraryPdf" class="light">${i.pdfName?'PDF ersetzen':'PDF hinterlegen'}</button>`:''}<button type="button" id="cancel" class="light">Abbrechen</button></div></form><p class="hint">Bei einer neuen Anleitung zuerst speichern, danach die PDF hinterlegen.</p>`);$('instructionLibraryForm').onsubmit=e=>{e.preventDefault();const f=e.target.elements,val={id:i.id,title:f.title.value.trim(),pumpModel:f.pumpModel.value.trim(),text:f.text.value.trim(),pdfName:i.pdfName||'',pdfUri:i.pdfUri||''};if(change(s=>{const x=s.instructionLibrary.findIndex(x=>x.id===val.id);if(x<0)s.instructionLibrary.push(val);else s.instructionLibrary[x]=val;})){$('modal').close();instructionLibraryPanel();toast('Gemeinsame Anleitung gespeichert.');}};if($('chooseLibraryPdf'))$('chooseLibraryPdf').onclick=()=>Native.chooseInstructionPdf('library:'+i.id);}
window.instructionPdfSelected=(target,uri,name)=>{try{if(target.startsWith('library:')){const id=target.slice(8),i=instructionById(id);if(!i)return toast('Die Anleitung wurde nicht gefunden.');const old=i.pdfUri||'';if(change(s=>{const t=s.instructionLibrary.find(x=>x.id===id);t.pdfUri=uri;t.pdfName=name||'Hantierungsanweisung.pdf';})){if(old&&old!==uri&&Native.releaseInstructionPdf)Native.releaseInstructionPdf(old);$('modal').close();instructionLibraryPanel();toast('PDF in der gemeinsamen Anleitung hinterlegt.');}}else{const assetId=target.startsWith('asset:')?target.slice(6):target,a=state.assets.find(x=>x.id===assetId);if(!a)return toast('Die Anlage für diese PDF wurde nicht gefunden.');const old=a.handlingInstruction&&a.handlingInstruction.pdfUri||'';if(change(s=>{const t=s.assets.find(x=>x.id===assetId);t.handlingInstruction.pdfUri=uri;t.handlingInstruction.pdfName=name||'Hantierungsanweisung.pdf';})){if(old&&old!==uri&&Native.releaseInstructionPdf)Native.releaseInstructionPdf(old);if(selected===assetId)showDetail(assetId,false);toast('Anlagenspezifische PDF hinterlegt.');}}}catch(e){toast('PDF konnte nicht hinterlegt werden.');}};

// Anlagenbuch 2.02: eigener Text-QR-Erfasser statt Samsung-Textfenster
window.scanTextQr=function(){
 modal(`<h2>QR-Code scannen</h2><p class="hint">Fotografiere den QR-Code. Anlagenbuch liest auch reine Text-QRs wie <strong>V-VA-CVD422 B</strong> und öffnet direkt die passende Unit.</p><input id="qrPhotoInput" type="file" accept="image/*" capture="environment"><div class="actions"><button id="qrChoosePhoto" type="button">Kamera / Foto öffnen</button></div><label>Alternativ QR-Text eingeben</label><input id="qrManualText" placeholder="z. B. V-VA-CVD422 B"><div class="actions"><button id="qrUseText" type="button">Unit öffnen</button><button id="cancel" type="button" class="light">Abbrechen</button></div><p id="qrScanState" class="hint"></p>`);
 const inp=$('qrPhotoInput'),stateEl=$('qrScanState');
 $('qrChoosePhoto').onclick=()=>inp.click();
 $('qrUseText').onclick=()=>{const v=$('qrManualText').value.trim();if(!v)return toast('Bitte QR-Text eingeben.');if(!window.openScannedText(v))toast('Keine passende Anlage oder Unit gefunden: '+v);};
 inp.onchange=async()=>{const f=inp.files&&inp.files[0];if(!f)return;stateEl.textContent='QR-Code wird ausgewertet …';try{if(!('BarcodeDetector' in window))throw new Error('BarcodeDetector nicht verfügbar');const bmp=await createImageBitmap(f);const d=new BarcodeDetector({formats:['qr_code']});const rows=await d.detect(bmp);if(bmp.close)bmp.close();if(!rows.length)throw new Error('Kein QR-Code erkannt');const raw=String(rows[0].rawValue||'').trim();$('qrManualText').value=raw;stateEl.textContent='Erkannt: '+raw;if(!window.openScannedText(raw))toast('QR-Code erkannt, aber keine passende Anlage oder Unit gefunden: '+raw);}catch(e){stateEl.textContent='Automatische QR-Erkennung ist auf diesem Gerät nicht verfügbar oder der Code war nicht lesbar. Du kannst den QR-Text unten eingeben.';}};
};
window.handleQrScanResult=function(raw){
 raw=String(raw||'').trim();if(!raw)return false;
 try{if(raw.startsWith('AB1-')&&window.Native&&Native.importTeamSetup){Native.importTeamSetup(raw);return true;}const u=new URL(raw);if(u.protocol==='de.modulbuch.anlagen:'){const setup=u.searchParams.get('setup');if(setup&&window.Native&&Native.importTeamSetup){Native.importTeamSetup(setup);return true;}}}catch(_){}
 if(window.openScannedText&&window.openScannedText(raw))return true;
 toast('QR-Code erkannt, aber keine passende Anlage oder Unit gefunden: '+raw);return false;
};
function scanQr(){try{if(window.Native&&Native.scanQr){Native.scanQr();return;}}catch(_){}if(window.scanTextQr)return window.scanTextQr();toast('QR-Scanner ist auf diesem Gerät nicht verfügbar.');}
window.openAssetFromQr=id=>{try{if(window.openScannedText&&window.openScannedText(id))return;const a=state&&state.assets.find(x=>x.id===id);if(!a)return toast('Diese Anlage / Unit ist in diesem Datenstand nicht vorhanden.');if($('modal').open)$('modal').close();showDetail(id);toast('QR-Code erkannt: '+a.name);}catch(e){toast('QR-Code konnte nicht geöffnet werden.');}};
function goHome(){if(navReady&&!navApplying&&selected){try{history.back();return;}catch(_){}}navApplyHome();}
function modal(html){$('modalContent').innerHTML=html;if(!$('modal').open)$('modal').showModal();const cancel=$('cancel');if(cancel)cancel.onclick=()=>$('modal').close();}
function assetForm(id){const a=state.assets.find(x=>x.id===id)||{name:'',module:$('moduleFilter').value||state.modules[0],y:'',x:'',verified:false};
 modal(`<h2>${id?'Anlage bearbeiten':'Neue Anlage'}</h2><form id="assetForm"><label for="name">Anlagenbezeichnung</label><input id="name" name="assetName" value="${esc(a.name)}" required maxlength="100" autocapitalize="characters"><label for="mod">Modul</label><select id="mod" name="mod">${options(a.module)}</select><div class="formrow"><div><label for="y">Koordinate Y (Buchstabe)</label><input id="y" name="y" value="${esc(a.y)}" maxlength="20" required autocapitalize="characters"></div><div><label for="x">Koordinate X (Zahl)</label><input id="x" name="x" value="${esc(a.x)}" maxlength="20" required inputmode="numeric"></div></div><label class="check"><input type="checkbox" name="verified" ${a.verified?'checked':''}> Ich habe diese Angaben geprüft.</label><p class="hint">Neue Module legst du unter „Module verwalten“ an.</p><div class="actions"><button type="submit">Speichern</button><button type="button" id="cancel" class="light">Abbrechen</button>${id?'<button type="button" id="deleteAsset" class="danger">Anlage löschen</button>':''}</div></form>`);
 $('assetForm').onsubmit=e=>{e.preventDefault();const f=e.target.elements;const values={name:f.assetName.value.trim().toUpperCase(),module:f.mod.value,y:f.y.value.trim().toUpperCase(),x:f.x.value.trim(),verified:f.verified.checked};const newId=id||uid();if(change(s=>{if(id){const target=s.assets.find(x=>x.id===id),oldName=String(target.name||'').trim();if(oldName!==values.name){for(const u of (target.units||[])){const oldAuto=('V-VA-'+oldName+' '+String(u.name||'').trim()).trim(),current=String(u.barcode||'').trim();if(!current||current===oldAuto)u.barcode=('V-VA-'+values.name+' '+String(u.name||'').trim()).trim();}}Object.assign(target,values);}else s.assets.push({...values,id:newId,notes:[],...C.equipment()});})){$('modal').close();showDetail(newId);toast('Anlage gespeichert.');}};
 for(const key of ['assetName','mod','y','x'])$('assetForm').elements[key].addEventListener('input',()=>{$('assetForm').elements.verified.checked=false;});
 if(id)$('deleteAsset').onclick=()=>{if(confirm(`„${a.name}“ mit allen Notizen, Hantierungsanweisungen, Ersatzteilen, Ablesungen und Sollwerten endgültig löschen?`)){if(change(s=>s.assets=s.assets.filter(x=>x.id!==id))){$('modal').close();goHome();toast('Anlage gelöscht.');}}};
}
function noteForm(id){const a=state.assets.find(x=>x.id===selected);const n=a.notes.find(x=>x.id===id)||{date:today(),text:'',workType:'turnus',technicians:''};const type=n.workType||'sonstiges';modal(`<h2>${id?'Eintrag bearbeiten':'Arbeit eintragen'}</h2><p>${esc(a.name)} · ${esc(a.module)}</p><form id="noteForm"><label for="date">Datum</label><input type="date" id="date" name="date" value="${esc(n.date)}" required><label for="workType">Art der Arbeit</label><select id="workType" name="workType"><option value="stoerung" ${type==='stoerung'?'selected':''}>Störung</option><option value="turnus" ${type==='turnus'?'selected':''}>Turnusmäßige Wartung / Wechsel</option><option value="sonstiges" ${type==='sonstiges'?'selected':''}>Sonstige Arbeit</option></select><label for="technicians">Monteure (Namen)</label><input id="technicians" name="technicians" value="${esc(n.technicians||'')}" required maxlength="500" placeholder="z. B. Ringel, Müller"><label for="text">Notiz / durchgeführte Arbeit</label><textarea id="text" name="text" required maxlength="10000" placeholder="z. B. Filter gewechselt und Funktion geprüft">${esc(n.text)}</textarea><p class="hint">Dieser Eintrag erscheint automatisch im Tagesprotokoll des gewählten Datums.</p><div class="actions"><button type="submit">Speichern</button><button type="button" id="cancel" class="light">Abbrechen</button></div></form>`);$('noteForm').onsubmit=e=>{e.preventDefault();const f=e.target.elements;const val={id:id||uid(),date:f.date.value,workType:f.workType.value,technicians:f.technicians.value.trim(),text:f.text.value.trim()};if(!val.technicians)return toast('Bitte die beteiligten Monteure eintragen.');const event=workSyncEvent('upsert',a,val);if(change(s=>{const notes=s.assets.find(x=>x.id===selected).notes;const i=notes.findIndex(x=>x.id===id);if(i<0)notes.push(val);else notes[i]=val;setWorkSyncMeta(s,event);})){queueWorkSync(event);$('modal').close();toast('Arbeit gespeichert und automatisch zur Synchronisierung vorgemerkt.');}};}
function modules(){modal(`<h2>Module verwalten</h2><p class="hint">Umbenennen ändert das Modul bei allen zugehörigen Anlagen.</p>${state.modules.map(m=>`<div class="moduleRow"><span>${esc(m)}<br><small>${state.assets.filter(a=>a.module===m).length} Anlagen</small></span><button class="light" data-rename="${esc(m)}">Umbenennen</button><button class="danger" data-del-module="${esc(m)}">Löschen</button></div>`).join('')}<form id="newModule"><label for="newMod">Neues Modul</label><input id="newMod" name="name" placeholder="z. B. Modul 3" required maxlength="100"><div class="actions"><button>Hinzufügen</button><button id="cancel" type="button" class="light">Fertig</button></div></form>`);$('newModule').onsubmit=e=>{e.preventDefault();const name=e.target.elements.name.value.trim();if(state.modules.some(m=>m.toLowerCase()===name.toLowerCase())){toast('Dieses Modul ist bereits vorhanden.');return;}if(change(s=>s.modules.push(name))){$('modal').close();modules();}};}
function renameModule(old){$('modal').close();modal(`<h2>Modul umbenennen</h2><form id="renameForm"><label for="rename">Modulname</label><input id="rename" name="name" value="${esc(old)}" required maxlength="100"><div class="actions"><button>Speichern</button><button type="button" class="light" id="cancel">Abbrechen</button></div></form>`);$('renameForm').onsubmit=e=>{e.preventDefault();const name=e.target.elements.name.value.trim();if(state.modules.some(m=>m!==old&&m.toLowerCase()===name.toLowerCase()))return toast('Dieser Modulname ist bereits vergeben.');if(change(s=>{s.modules=s.modules.map(m=>m===old?name:m);s.assets.forEach(a=>{if(a.module===old)a.module=name;});})){$('modal').close();modules();}};}
