// A whole-app snapshot must not roll back independently synchronized faults.
function mergeFaultHistory(backup,current){
 const out=C.clone(backup),cur=C.clone(current);
 out.faultSyncMeta=out.faultSyncMeta||{};
 const local=new Map(),remote=new Map();
 for(const a of cur.assets)for(const f of a.faults||[])local.set(f.id,{asset:a,fault:f});
 for(const a of out.assets)for(const f of a.faults||[])remote.set(f.id,{asset:a,fault:f});
 const remove=id=>{for(const a of out.assets)a.faults=(a.faults||[]).filter(f=>f.id!==id);};
 for(const id of new Set([...local.keys(),...Object.keys(cur.faultSyncMeta||{})])){
  const m=(cur.faultSyncMeta||{})[id],old=out.faultSyncMeta[id],src=local.get(id);
  const same=m&&old&&m.at===old.at&&m.eventId===old.eventId;
  const take=m ? syncMetaNewer(m,old)||(same&&!remote.has(id)) : !old&&!remote.has(id);
  if(!take||(!src&&!(m&&m.deleted)))continue;
  remove(id);
  if(m)out.faultSyncMeta[id]=C.clone(m);
  if(m&&m.deleted)continue;
  let target=out.assets.find(a=>a.id===src.asset.id);
  if(!target){
   if(!out.modules.includes(src.asset.module))out.modules.push(src.asset.module);
   target=C.clone(src.asset);target.notes=[];target.faults=[];out.assets.push(target);
  }
  target.faults=target.faults||[];target.faults.push(C.clone(src.fault));
 }
 for(const [id,m] of Object.entries(out.faultSyncMeta))if(m.deleted)remove(id);
 return out;
}

