function recoverFaultSync164(){
 try{
  if(!window.Native||!Native.resetFaultSyncForRestore)return;
  if(localStorage.getItem('fault-history-recovery-164')==='started')return;
  // This resets only the download cursor, never data or event timestamps.
  Native.resetFaultSyncForRestore();
  localStorage.setItem('fault-history-recovery-164','started');
 }catch(e){console.warn('Störungsabgleich wird beim nächsten Start erneut versucht',e);}
}

setTimeout(recoverFaultSync164,500);
